(async()=>{
 const $=id=>document.getElementById(id)||document.getElementById(({'mock-trainer':'player-sprite','mock-enemy':'enemy-sprite'})[id]||''),workshop=document.body.dataset.view==='workshop';MockScenery.paint($('world-scene'),workshop?'workshop':'battle');TrainerStudy.draw($('mock-trainer'));
 const message=(text,hint)=>{$('mock-dialogue').textContent=text;if(hint)$('mock-hint').textContent=hint;};
 if(workshop){
  const canvas=$('mock-drawing'),ctx=canvas.getContext('2d');let drawing=false,hasDrawing=false;const position=e=>{const b=canvas.getBoundingClientRect();return[(e.clientX-b.left)*canvas.width/b.width,(e.clientY-b.top)*canvas.height/b.height];};
  canvas.addEventListener('pointerdown',e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...position(e));ctx.strokeStyle=GamePalette.tokens.ink;ctx.lineWidth=3;ctx.lineCap='round';$('paper-prompt').hidden=true;hasDrawing=true;});canvas.addEventListener('pointermove',e=>{if(!drawing)return;ctx.lineTo(...position(e));ctx.stroke();});for(const event of ['pointerup','pointercancel'])canvas.addEventListener(event,()=>drawing=false);
  $('mock-clear').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);$('paper-prompt').hidden=false;hasDrawing=false;};$('mock-settings-toggle').onclick=()=>{$('mock-settings').hidden=!$('mock-settings').hidden;$('mock-settings-toggle').setAttribute('aria-expanded',String(!$('mock-settings').hidden));};$('mock-grade').onchange=()=>{$('mock-grade-note').textContent=$('mock-grade').value==='random'?'랜덤 등급으로 제작':'지정 등급 · '+$('mock-grade').selectedOptions[0].textContent;};
  $('mock-create').onclick=()=>message(hasDrawing?'이 그림을 무기로 깨우는 순간.':'어떤 무기를 만들까? 먼저 한 획을 그어봐.','디자인 목업이야. 실제 제작과 저장은 기존 공방에 그대로 있어.');$('mock-example').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle=GamePalette.tokens.ink;ctx.lineWidth=3;ctx.beginPath();for(const[x,y]of [[160,204],[179,180],[164,165],[187,142],[173,126],[195,104],[184,89],[205,78]]){if(x===160)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();ctx.beginPath();ctx.moveTo(205,78);ctx.bezierCurveTo(168,72,191,38,208,57);ctx.bezierCurveTo(207,27,227,39,228,53);ctx.bezierCurveTo(246,42,252,64,238,70);ctx.bezierCurveTo(249,87,220,94,205,78);ctx.stroke();$('paper-prompt').hidden=true;hasDrawing=true;message('번개를 품은 구름 봉은 어떨까?','모양을 더하거나, 완전히 다른 그림으로 바꿔봐.');};
 }else{
  BattlePreview.drawSprites(0);GameStageLayout.attach($('world-scene').parentElement,$('mock-enemy'),$('mock-enemy'));$('mock-enemy').setAttribute('aria-label','가시잎 수호자 도트 캐릭터');let hp=110,busy=false,atlas;const moves=[{name:'지그재그 스파크',type:'electric',pp:14,damage:24},{name:'유령 구름 강타',type:'ghost',pp:12,damage:28},{name:'마비의 방전',type:'electric',pp:16,damage:16},{name:'지그재그 참격',type:'ghost',pp:19,damage:20}];
  try{const r=await fetch('assets/studies/blueprints/spring-hand.json'),data=await r.json(),image=new Image();image.src=data.image;await image.decode();const canvas=$('mock-weapon'),c=canvas.getContext('2d');c.drawImage(image,0,0,canvas.width,canvas.height);const pixels=c.getImageData(0,0,canvas.width,canvas.height);for(let i=0;i<pixels.data.length;i+=4)if(pixels.data[i]>235&&pixels.data[i+1]>235&&pixels.data[i+2]>235)pixels.data[i+3]=0;c.putImageData(pixels,0,0);}catch{}
  async function cast(index){if(busy)return;busy=true;const move=moves[index],damage=Math.round((move.damage+14)*Craft.Types.multiplier(move.type,['nature']));$('mock-moves').hidden=true;$('mock-commands').hidden=false;message(move.name+'!\n가시잎 수호자에게 '+damage+' 피해!','전투 장면의 배치와 조작을 확인하는 목업이야.');hp=Math.max(0,hp-damage);$('enemy-hp').style.width=hp/110*100+'%';$('mock-enemy').classList.add('hit');
   try{atlas=await BattleSpriteAtlas.loadGenerated('3baed2b894b87a2baa17c49c65431a8c81c604349ba4b4529bdb84cb74cd21ea',move.type,{allowFadeEmpty:true});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const canvas=$('mock-effect'),box=canvas.getBoundingClientRect();canvas.width=box.width;canvas.height=box.height;const c=canvas.getContext('2d');await new Promise(resolve=>{let start;const frame=now=>{if(start===undefined)start=now;const q=Math.min(1,(now-start)/650);c.clearRect(0,0,canvas.width,canvas.height);BattleSpriteAtlas.drawFrame(c,atlas,index,Math.min(3,Math.floor(q*4)),box.width*.8,box.height*.43,box.height*.55,{alpha:1-q*.3});if(q<1)requestAnimationFrame(frame);else{c.clearRect(0,0,canvas.width,canvas.height);resolve();}};requestAnimationFrame(frame);});}}catch{}
   $('mock-enemy').classList.remove('hit');if(!hp){$('mock-enemy').classList.add('defeated');message('가시잎 수호자를 물리쳤다!','이 목업의 전투 기록은 저장되지 않아.');}busy=false;
  }
  moves.forEach((move,index)=>{const button=document.createElement('button');button.type='button';button.className='mock-move';button.style.setProperty('--type-color',Craft.Types.color(move.type));const name=document.createElement('strong'),detail=document.createElement('small');name.textContent=move.name;detail.textContent=Craft.Types.label(move.type)+' · PP '+move.pp+'/'+move.pp;button.append(name,detail);button.onclick=()=>cast(index);$('mock-moves').append(button);});
  $('mock-fight').onclick=()=>{if(busy)return;$('mock-moves').hidden=false;$('mock-commands').hidden=true;message('어떤 기술로 맞설까?','기술마다 다른 힘이 깃들어 있어.');};for(const id of ['mock-guard','mock-bag','mock-info'])$(id).onclick=()=>message(id==='mock-guard'?'상대의 다음 공격에 대비했다.':id==='mock-bag'?'가방에는 잉크 물약이 하나 남아 있어.':'번개 구름 채찍봉\n전기 / 고스트 · 신화','배치와 조작을 확인하는 디자인 목업이야.');$('mock-reset').onclick=()=>{hp=110;$('enemy-hp').style.width='100%';$('mock-enemy').classList.remove('defeated');$('mock-moves').hidden=true;$('mock-commands').hidden=false;message('가시잎 수호자가 길을 막아섰다!\n번개 구름 채찍봉으로 맞서볼까?','상대의 다음 행동을 보고 기술을 골라봐.');};
 }
})();
